'use strict';
const EN = {filmTitle:'See how one piece of work<br>leads to the next.',filmText:'From a lecture to your own understanding. From saved knowledge to the next task. See how AI Bro connects the work in 1 minute 46 seconds.',filmCaption:'Example workspace · Real UI interactions and saves · Scripted model responses, edited for pacing',filmDownload:'Download the film ↓',videoFallback:'Your browser cannot play this video. Download it to watch locally.',
 skip:'Skip to content',navLabel:'Main navigation',navWorkspace:'Workflow',navScenarios:'Use cases',navControl:'Your controls',navDownload:'Get AI Bro',heroTitle:'Your knowledge. Your next move.',heroExplore:'Watch the product film ↓',heroDownload:'Get the Mac app',heroSource:'Build from source ↗',heroMeta:'Local first · Chinese & English · Your choice of models',exploreLabel:'Explore the product',intro1:'Every conversation.',intro2:'A place to pick up from.',introText:'A lecture can become more than a summary. A paper can become more than a single answer. Connect source material, your understanding, and next steps—then keep working with AI as your knowledge grows.',flowLabel:'How sources, knowledge, and actions connect',flowInput:'What you bring',flowWeb:'Web pages & papers',flowIdeas:'Ideas & plans',flowCenter:'Converse · Organize · Act',flowOutput:'What you can build on',flowNotes:'Editable notes',flowProjects:'Projects & files',flowTasks:'Tasks & progress',flowReturn:'Saved knowledge comes back into the next conversation.',workspaceTitle:'From “take a look”<br>to “let’s keep going.”',workspaceText:'Ask AI, check the source, add your understanding, and follow up—all in one workspace. Each step leaves something you can open and change.',tabsLabel:'Explore product features',examplePrompt:'Try asking',expand:'View larger ↗',expandLabel:'Enlarge the actual app interface',scenariosTitle:'Learning. Research. Life.<br>Organized, and connected.',scenariosText:'One structure for knowledge and action, adapted to different kinds of work. Keep spaces distinct while following connections through projects, sources, and conversations.',courseTitle:'Give your course a throughline.',courseText:'Organize slides by course and chapter, keep the analysis in editable Markdown, and read it alongside the original. Link learning goals, assessment requirements, and next steps.',courseTreeRoot:'Interaction Design Methods',courseTree1:'├ Lecture 01',courseTree2:'│ ├ Lecture slides.pdf',courseTree3:'│ └ Study notes.md',courseTree4:'└ Task · Conduct an interview',courseLink:'Explore reading and editing ↗',researchTitle:'Put your papers to work.',researchText:'Start with a paper link or file. Capture methods, experiments, limitations, and your own insights. Connect originals, research notes, and citation relationships, with deduplication and updates.',topic1:'Contributions',topic2:'Methods & experiments',topic3:'Limitations',topic4:'Research insights',topic5:'Sources & citations',researchLink:'Explore the literature library ↗',dailyTitle:'Give a passing thought a next step.',dailyText:'Bring trips, personal projects, and everyday tasks to AI. Add a deadline or change a plan in a follow-up; update the original task, or edit, move, and complete it yourself.',dailyBubble:'“Move the deadline for packing<br>to tomorrow at 4 pm.”',dailyResult:'Original task updated · Checklist retained',dailyLink:'Explore task follow-ups ↗',reuseTitle:'A new conversation.<br>Not a fresh start.',reuseText:'Mention a course or project in a new chat. AI retrieves relevant saved notes and materials, with sources you can open to check the answer and add your understanding—without digging through old conversations.',reusePrompt:'“From my course notes, explain how observation differs from interviewing. Include sources. Answer only; don’t change anything.”',reuseLink:'Explore knowledge Q&A ↗',reuseExpand:'Enlarge knowledge Q&A',reuseAlt:'A new conversation using saved project knowledge and linked sources',reuseCaption:'Actual app interface · Example project and materials',progressTitle:'See the progress.<br>Return to the work.',progressText:'Task completion, activity trends, and a planning timeline together. Inspect a day and open the tasks or sources behind it, turning a chart into a way back to your work.',progressExpand:'Enlarge activity analytics',progressAlt:'D3 activity trends with real item details',progress1:'Time in context',progress1Text:'7 / 30-day activity trends and a timeline with actual dates.',progress2:'Numbers with sources',progress2Text:'Hover for details, select a date, and open the underlying items.',progress3:'Plans you can change',progress3Text:'Complete tasks, adjust priorities and dates, or move them to a project.',controlTitle:'Make it work your way.',controlText:'You don’t have to use one model for everything, or send every file to the same cloud.',privacyText:'Saved locally. Connected when you choose. Using a model sends relevant content to your provider; enabling sync sends supported data to your own server. Model credentials and local folder permissions are not synced with the workspace.',detailsTitle:'The everyday details<br>deserve attention, too.',detailsText:'A workspace you can resize, content you can recover, and status you can see. Small interactions that make complex work feel manageable.',downloadTitle:'Bring AI Bro into<br>your next project.',downloadIntro:'Preview source is public and ready to build. The first public App package is being prepared; check Releases for availability.',downloadApp:'Download the Mac app',downloadAppText:'For Apple Silicon Macs running macOS 12 or later. Python and PDF runtimes are included; no separate installation needed.',downloadAppLink:'Open GitHub Releases ↗',downloadAppNote:'The preview is not Apple-notarized. Native glass requires macOS 26.',downloadSource:'Build from source',downloadSourceText:'Explore the source, run the local service, or build your own desktop app. The guide covers requirements, building, and version verification.',downloadSourceLink:'Read the build guide ↗',downloadSourceNote:'Development builds require Node.js and Python. See the guide for dependencies.',releaseNotes:'Release notes ↗',syncGuide:'Self-hosted sync guide ↗',repository:'GitHub repository ↗',footerText:'Knowledge grows. Work moves forward.',footerNote:'Interfaces use isolated example workspaces, with no personal data.',dialogLabel:'Enlarged product interface',dialogTitle:'AI Bro · Actual app interface',closeLabel:'Close'
};
const FEATURES = [
 {id:'intake',asset:'course-intake',zh:['交给 AI 整理','资料，进入合适的位置。','拖入课件、论文或文档，粘贴网页，再说出需求。AI 根据内容与上下文判断空间和项目，保留原件，整理笔记与行动项。',['对话中拖入文件，随指令交给 AI','项目内直接导入可保留为「待 AI 分析」','处理进度与执行结果可展开查看'],'「整理这份课件，保留原件，生成主笔记和合理的下一步。」','AI 整理后的项目、原件、笔记与任务'],en:['Organize with AI','One source. A place to belong.','Drop in slides, papers, or documents, paste a web link, and describe what you need. AI uses content and context to suggest the space and project, preserve the original, and organize notes and actions.',['Drop files into a conversation with your request','Direct project imports can stay marked “Awaiting AI analysis”','Inspect processing progress and execution results'],'“Organize these slides. Keep the original, make a main note, and suggest next steps.”','Projects, originals, notes, and tasks after organization']},
 {id:'read',asset:'read-edit',zh:['阅读与编辑','原件在旁，理解由你完善。','笔记与 PDF 在标签式阅读区打开，和对话并排。直接编辑 Markdown 并保存，合并相关分析，减少零碎文档。',['可调节分区宽度，切换多个阅读标签','笔记连接原始来源与页码','主笔记可编辑、保存和导出 Markdown'],'「把这几条分析合并到主笔记，保留我的补充和来源。」','可编辑 Markdown 与并排阅读区'],en:['Read & edit','Keep the source close. Make the understanding yours.','Open notes and PDFs in a tabbed reading pane beside the conversation. Edit and save Markdown directly, combining related analysis instead of accumulating fragments.',['Resize panes and switch reading tabs','Follow source and page references','Edit, save, and export the main Markdown note'],'“Merge these analyses into the main note. Keep my additions and the sources.”','Editable Markdown in the side-by-side reading area']},
 {id:'knowledge',asset:'knowledge-reuse',zh:['知识库问答','保存过的知识，能继续用。','无需回到原来的会话。在新对话里提到项目或课程，检索已有知识，关联回答依据，并从来源继续阅读。',['跨会话检索相关项目与笔记','只问答时，保留已有内容不变','来源可打开核对，知识可持续补充'],'「根据课程项目的笔记，解释这两个概念的区别，标明依据。」','新会话引用项目知识与原始来源'],en:['Knowledge Q&A','Saved knowledge you can use again.','You don’t have to find the original chat. Mention a project or course in a new conversation to retrieve saved knowledge, inspect the evidence, and keep reading from its sources.',['Retrieve relevant projects and notes across chats','Ask for an answer without changing saved content','Open sources and keep refining your knowledge'],'“Use my course notes to explain the difference between these concepts. Include sources.”','A fresh conversation using project knowledge and sources']},
 {id:'research',asset:'research-library',zh:['文献与研究','从读过一篇，到建立研究脉络。','论文库、结构化分析与研究笔记彼此关联。按项目和主题归类，查看引用与相关关系，让文献积累成可查阅的研究资料。',['DOI、arXiv 与链接去重、增量更新','方法、实验、局限与启发集中整理','引用关系与主题关联区分呈现'],'「分析这篇论文，和项目里已有文献比较，更新研究笔记。」','论文库与关联网络'],en:['Literature & research','From reading a paper to building a research trail.','Connect your paper library, structured analysis, and research notes. Organize by project and topic, then explore citations and related work as the library grows.',['Deduplicate and update by DOI, arXiv, or link','Collect methods, experiments, limitations, and insights','Distinguish citations from topic relationships'],'“Analyze this paper, compare it with the project literature, and update my research note.”','The paper library and relationship network']},
 {id:'tasks',asset:'daily-update',zh:['任务与行动','改变安排，更新原来的任务。','从对话里生成任务，后续继续补充截止时间、状态和检查清单。也可以手动新增、编辑或移动，清楚知道接下来做什么。',['任务保留所属项目和来源','后续指令可更新已有事项','删除进入回收站，支持恢复与批量管理'],'「把准备装备的截止时间改成明天下午四点，清单保留。」','对话更新已有任务的截止时间'],en:['Tasks & actions','Change the plan. Update the same task.','Create a task in conversation and add a deadline, status, or checklist later. Add, edit, and move items manually whenever you need to.',['Keep tasks linked to projects and sources','Update existing items in follow-up messages','Recover deleted content and manage items in batches'],'“Move the packing deadline to tomorrow at 4 pm. Keep the checklist.”','A follow-up updating the original task deadline']},
 {id:'models',asset:'personal-workspace',zh:['模型与 Skills','每段对话，都有自己的选择。','在会话里切换模型与推理强度。用 Skills 复用论文深读、课程学习等工作方式，一键润色提示词也可以单独选模型。',['本机官方 Codex 登录或兼容自定义 API','模型与推理调整作用于后续消息','内置与自定义 Skills，按需启用'],'「这次深入分析，换一个适合长文推理的模型。」','会话内的模型与推理设置'],en:['Models & Skills','Different conversations. Different choices.','Change the model and reasoning effort in a conversation. Reuse research or study workflows with Skills, and choose a separate model for one-click prompt refinement.',['Local official Codex sign-in or a compatible custom API','Model changes apply to subsequent messages','Built-in and custom Skills, enabled when needed'],'“For this deeper analysis, use a model suited to long-form reasoning.”','Model and reasoning controls within a conversation']}
];
const CONTROLS = {
 zh:[['01','模型连接','本机 Codex 登录或自定义 API。按会话切换模型和推理强度，润色提示词还可以另选模型。','账号登录需要单独安装官方 Codex CLI；能力取决于所选模型。'],['02','本机项目关联','在授权目录中按线索寻找本地项目，确认后保存目录关联。以后从项目继续对话，不必反复定位路径。','本机目录授权留在当前设备，不自动上传整个源码目录。'],['03','自托管增量同步','连接自己的服务器，在个人设备间同步支持的项目、知识、对话和受管资料。查看状态，处理版本冲突。','同步服务需自行部署；当前不提供端到端加密或实时多人协作。'],['04','可选择的操作权限','按会话选择审批方式。查看执行过程，核对动作与成果；需要时可以停止当前请求。','文件、联网与执行能力受当前通道及授权范围约束。']],
 en:[['01','Connect your models','Use local Codex sign-in or a compatible custom API. Change models and reasoning per chat, with a separate choice for prompt refinement.','Account sign-in requires the official Codex CLI installed separately. Capabilities depend on the model.'],['02','Connect local projects','Find a local project by clues within approved folders, then save the selected directory association. Continue from that project without finding its path again.','Local folder permissions stay on the current device. Source directories are not automatically uploaded in full.'],['03','Self-hosted incremental sync','Connect your own server to sync supported projects, knowledge, chats, and managed files across personal devices. See sync status and resolve conflicts.','Deploy and maintain your own server. End-to-end encryption and real-time team collaboration are not included.'],['04','Choose how actions are approved','Select an approval mode per conversation. Inspect execution progress, actions, and results, and stop a request when you need to.','File, network, and execution capabilities depend on the active connection and granted permissions.']]
};
const DETAILS={zh:[['随手拖入','对话区支持文件拖放，也支持选择文件和粘贴链接。'],['一篇主笔记','减少碎片分析，保留层次、来源和自己的编辑。'],['分区可调','拖动调节空间；文件、笔记、对话并排工作。'],['清楚的生命周期','待分析、已关联、已完成与回收记录各有状态。'],['中英双语','界面语言可切换，用户原文保持原文。'],['从第一步开始','新手引导、深浅外观、可恢复的删除与执行历史。']],en:[['Drop it in','Drag files into the conversation, browse for files, or paste a link.'],['One main note','Reduce scattered analyses while keeping structure, sources, and your edits.'],['Room to work','Resize panes and keep files, notes, and conversations side by side.'],['Visible lifecycle','See what awaits analysis, what is linked, and what is completed or deleted.'],['Chinese & English','Switch the interface language while preserving the original user content.'],['Start with guidance','First-run onboarding, light and dark appearance, recovery, and execution history.']]};
const zh=new Map();document.querySelectorAll('[data-t],[data-label],[data-alt]').forEach(el=>{for(const [a,v]of [['data-t',el.innerHTML],['data-label',el.getAttribute('aria-label')],['data-alt',el.getAttribute('alt')]])if(el.hasAttribute(a))zh.set(el.getAttribute(a),v)});
let lang=new URLSearchParams(location.search).get('lang')==='en'?'en':'zh';let selected='intake';let returnFocus=null;
const tablist=document.getElementById('feature-tabs');
function text(key){return lang==='en'?EN[key]:zh.get(key)}
function asset(name){return `assets/${name}-${lang}.jpg`}
function showFeature(id,focus=false){
 selected=id;const i=FEATURES.findIndex(f=>f.id===id);const f=FEATURES[i],c=f[lang];
 [...tablist.children].forEach(b=>{const on=b.dataset.id===id;b.setAttribute('aria-selected',String(on));b.tabIndex=on?0:-1});
 document.getElementById('feature-panel').setAttribute('aria-labelledby',`tab-${id}`);
 document.getElementById('feature-index').textContent=`${String(i+1).padStart(2,'0')} / 06`;
 document.getElementById('feature-title').textContent=c[1];document.getElementById('feature-description').textContent=c[2];document.getElementById('feature-prompt').textContent=c[4];document.getElementById('feature-caption').textContent=c[5];
 document.getElementById('feature-points').replaceChildren(...c[3].map(t=>{const li=document.createElement('li');li.textContent=t;return li}));
 const im=document.getElementById('feature-shot');im.src=asset(f.asset);im.alt=c[5];im.dataset.current=f.asset;
 const crops={intake:[470,110,950,640],read:[800,35,630,800],knowledge:[500,125,910,615],research:[245,190,1150,680],tasks:[355,25,735,835],models:[920,320,410,560]};
 const [x,y,w,h]=crops[id];const stage=im.closest('.expand-shot');stage.style.aspectRatio=`${w}/${h}`;stage.dataset.feature=id;
 im.style.width=`${1440/w*100}%`;im.style.left=`${-x/w*100}%`;im.style.top=`${-y/h*100}%`;
 if(focus)document.getElementById(`tab-${id}`).focus();
}
function render(){
 document.documentElement.lang=lang==='en'?'en':'zh-CN';document.title=lang==='en'?'AI Bro — Your knowledge. Your next move.':'AI Bro — 知识与行动，在同一处';document.querySelector('meta[name="description"]').content=lang==='en'?'Connect conversations, editable notes, sources, tasks, and research. Explore AI Bro, your local-first personal AI workspace.':'从课件与论文，到可编辑笔记、任务与持续对话。探索 AI Bro 的个人知识库、科研工作流、灵活模型与自托管同步。';
 document.querySelectorAll('[data-t]').forEach(el=>{const value=text(el.dataset.t);if(value!=null)el.innerHTML=value});
 document.querySelectorAll('[data-label]').forEach(el=>el.setAttribute('aria-label',text(el.dataset.label)));
 document.querySelectorAll('[data-alt]').forEach(el=>el.alt=text(el.dataset.alt));
 document.querySelectorAll('[data-asset]').forEach(el=>el.src=asset(el.dataset.asset));
 const video=document.getElementById('product-film'); const nextFilm='assets/film-'+lang+'.mp4';
 if(video.querySelector('source').getAttribute('src')!==nextFilm){video.pause();video.poster='assets/film-'+lang+'.poster.jpg';video.querySelector('source').src=nextFilm;const track=video.querySelector('track');track.src='assets/film-'+lang+'.vtt';track.srclang=lang==='zh'?'zh-CN':'en';track.label=lang==='zh'?'中文':'English';video.load();}
 document.getElementById('film-download').href=nextFilm;
 const switcher=document.getElementById('language');switcher.textContent=lang==='en'?'中文':'EN';switcher.setAttribute('aria-label',lang==='en'?'切换至中文':'Switch to English');
 tablist.replaceChildren(...FEATURES.map(f=>{const b=document.createElement('button');b.type='button';b.id=`tab-${f.id}`;b.dataset.id=f.id;b.role='tab';b.setAttribute('aria-controls','feature-panel');b.textContent=f[lang][0];b.onclick=()=>showFeature(f.id);return b}));
 showFeature(selected);
 document.getElementById('control-grid').replaceChildren(...CONTROLS[lang].map(([num,title,body,note])=>{const a=document.createElement('article');const n=document.createElement('span');n.className='control-number';n.textContent=num;const h=document.createElement('h3');h.textContent=title;const p=document.createElement('p');p.textContent=body;const small=document.createElement('small');small.textContent=note;a.append(n,h,p,small);return a}));
 document.getElementById('detail-list').replaceChildren(...DETAILS[lang].map(([title,body])=>{const a=document.createElement('article');const h=document.createElement('h3');h.textContent=title;const p=document.createElement('p');p.textContent=body;a.append(h,p);return a}));
}
document.getElementById('language').onclick=()=>{lang=lang==='zh'?'en':'zh';const u=new URL(location.href);if(lang==='en')u.searchParams.set('lang','en');else u.searchParams.delete('lang');history.replaceState(null,'',u);render()};
tablist.addEventListener('keydown',e=>{const tabs=[...tablist.children];let i=tabs.findIndex(b=>b===document.activeElement);if(i<0)return;if(e.key==='ArrowRight')i=(i+1)%tabs.length;else if(e.key==='ArrowLeft')i=(i-1+tabs.length)%tabs.length;else if(e.key==='Home')i=0;else if(e.key==='End')i=tabs.length-1;else return;e.preventDefault();showFeature(tabs[i].dataset.id,true)});
document.querySelectorAll('[data-feature]').forEach(b=>b.onclick=()=>{showFeature(b.dataset.feature);document.getElementById('workspace').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth'});document.getElementById(`tab-${b.dataset.feature}`).focus({preventScroll:true})});
const dialog=document.getElementById('shot-dialog');function openShot(name,alt){returnFocus=document.activeElement;const im=document.getElementById('dialog-shot');im.src=asset(name);im.alt=alt;dialog.showModal();document.getElementById('close-shot').focus()}
document.getElementById('expand-feature').onclick=()=>{const f=FEATURES.find(f=>f.id===selected);openShot(f.asset,f[lang][5])};document.querySelectorAll('[data-shot]').forEach(b=>b.onclick=()=>openShot(b.dataset.shot,b.querySelector('img').alt));document.getElementById('close-shot').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close()});dialog.addEventListener('close',()=>returnFocus?.focus());
render();
